#include <stdatomic.h>
#include <pthread.h>
#include <immintrin.h>

typedef struct { atomic_flag lock; } spinlock_t;

void spinlock_init(spinlock_t *s){ atomic_flag_clear(&s->lock); }

void spinlock_acquire(spinlock_t *s){
  while (atomic_flag_test_and_set_explicit(&s->lock, memory_order_acquire)){
    _mm_pause();
  }
}

void spinlock_release(spinlock_t *s){
  atomic_flag_clear_explicit(&s->lock, memory_order_release);
}
